#include <QtCore>
#include "LegacyDecodeText.h"
bool isTimeSyncDecodeMode(const QString& s){return s=="FT8" || s=="MSK144";}
QString normalizeUtcDisplayToken(QString s){return s.remove(':');}
QString stripDecodeApAnnotation(QString s,QString* p){if(p)p->clear();return s;}
void bridgeLog(const QString&){}
QString decodeMirrorLooseKey(QVariantMap const& e){return e.value("db").toString()+"|"+e.value("dt").toString()+"|"+e.value("freq").toString()+"|"+e.value("message").toString();}
QString decodeMirrorEntryKey(QVariantMap const& e){return e.value("time").toString()+"|"+decodeMirrorLooseKey(e);}
struct DecodeUserFilterConfig{};DecodeUserFilterConfig readDecodeUserFilterConfig(){return {};}
bool shouldAcceptDecodeEntryByUserFilters(QVariantMap const& e,DecodeUserFilterConfig const&,bool,QString*){return !e.value("message").toString().contains("BLOCK");}
class DecodiumBridge {public:QString m_mode="FT8",path;mutable QString m_legacyAllTxtConsumedPath;mutable qint64 m_legacyAllTxtConsumedSize=-1;bool m_hideGhostDecodes=false;
 QString legacyAllTxtPath()const{return path;}bool shouldAcceptDecodedMessage(const QString& m,QString*)const{return !m.contains("REJECT");}bool messageMentionsLocalCall(const QString&)const{return false;}QString extractDecodedCallsign(const QString&,bool)const{return "K1ABC";}void enrichDecodeEntry(QVariantMap&)const{}bool looksLikeGhostDecode(const QVariantMap&)const{return false;}
 QVariantList augmentLegacyMirrorWithAllTxt(QVariantList const&,bool)const;};
